287	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
288	// 不可为空、集合不可为空且编号不可重复。
289	func cleanParcelList(raw []string) ([]string, error) {
290		if len(raw) == 0 {
291			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
292		}
293		clean := make([]string, 0, len(raw))
294		seen := make(map[string]bool, len(raw))
295		for _, v := range raw {
296			id, err := cleanID("包裹编号", v)
297			if err != nil {
298				return nil, err
299			}
300			if seen[id] {
301				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
302			}
303			seen[id] = true
304			clean = append(clean, id)
305		}
306		return clean, nil
307	}
