366	func cmdReceipt(dataFile string, argv []string, stdout, stderr io.Writer) int {
367		fs := newFlagSet("receipt", stderr)
368		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
369		request := fs.String("request", "", "回执请求号（用于去重）")
370		batch := fs.String("batch", "", "配送批次号")
371		parcel := fs.String("parcel", "", "包裹编号")
372		result := fs.String("result", "", "回执结果：签收 或 失败")
373		reason := fs.String("reason", "", "失败原因（结果为失败时必填，签收时不可带）")
374		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptHelp); !ok {
375			return code
376		}
377	
378		cleanReq, err := cleanID("回执请求号", *request)
379		if err != nil {
380			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
381			return exitBusiness
382		}
383		cleanBatch, err := cleanID("批次号", *batch)
384		if err != nil {
385			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
386			return exitBusiness
387		}
388		cleanParcel, err := cleanID("包裹编号", *parcel)
389		if err != nil {
390			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
391			return exitBusiness
392		}
393		cleanResult, err := cleanID("回执结果", *result)
394		if err != nil {
395			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
396			return exitBusiness
397		}
398		if cleanResult != resultSigned && cleanResult != resultFailed {
399			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
400			return exitBusiness
401		}
402		cleanReason := strings.TrimSpace(*reason)
403		if cleanResult == resultFailed && cleanReason == "" {
404			fmt.Fprintf(stderr, "%s receipt: 结果为失败时原因不可为空或仅含空白\n", appName)
405			return exitBusiness
406		}
407		if cleanResult == resultSigned && cleanReason != "" {
408			fmt.Fprintf(stderr, "%s receipt: 结果为签收时不可带原因\n", appName)
409			return exitBusiness
410		}
411	
412		store, err := Open(dataFile)
413		if err != nil {
414			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
415			return exitBusiness
416		}
417		res, replayed, err := store.Receipt(cleanReq, cleanBatch, cleanParcel, cleanResult, cleanReason, now())
418		if err != nil {
419			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
420			return exitBusiness
421		}
422	
423		headline := "回执成功"
424		if replayed {
425			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
426		}
427		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
428			headline, res.Request, res.Batch, res.Parcel, res.Result)
429		if res.Result == resultFailed {
430			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
431		}
432		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
433		return exitOK
434	}
