551		fmt.Fprintf(stdout, "回执导入成功（共 %d 条：新增 %d 条，重放 %d 条）\n", len(items), len(items)-replayed, replayed)
552		for i, it := range items {
553			mark := "新增"
554			if it.Replayed {
555				mark = "重放（返回首次保存的结果）"
556			}
557			line := fmt.Sprintf("  %d. 请求号: %s    批次号: %s    包裹编号: %s    结果: %s",
558				i+1, it.Record.Request, it.Record.Batch, it.Record.Parcel, it.Record.Result)
559			if it.Record.Result == resultFailed {
560				line += fmt.Sprintf("    原因: %s", it.Record.Reason)
561			}
562			fmt.Fprintf(stdout, "%s    标记: %s    时间: %s\n", line, mark, it.Time.Format(timeFmt))
563		}
564		return exitOK
565	}
