1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// 包裹状态。
15	const (
16		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
17		statusInStation = "在站"
18		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
19		statusDelivering = "配送中"
20		// statusSigned 表示包裹已签收（回执结果为签收）。
21		statusSigned = "已签收"
22		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
23		statusFrozen = "异常冻结"
24	)
25	
26	// 回执结果。
27	const (
28		resultSigned = "签收"
29		resultFailed = "失败"
30	)
31	
32	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
33	type Event struct {
34		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接
35		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接为批次出发站）
36		Time       time.Time `json:"time"`                 // 发生时间
37		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接请求号（收件、出站记录为空）
38		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
39		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）或续接原因（仅续接记录有）
40		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）
41		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接记录有；续接时为新批次号）
42		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
43		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
44		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
45		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
46		Incident string `json:"incident,omitempty"`
47		Note     string `json:"note,omitempty"`
48	}
49	
50	// Parcel 是一件包裹的台账信息。
51	type Parcel struct {
52		ID         string    `json:"id"`
53		Station    string    `json:"station"`    // 当前归属站点
54		Status     string    `json:"status"`     // 当前状态
55		Registered time.Time `json:"registered"` // 收件时间
56		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
57	}
58	
59	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
60	type HandoffResult struct {
61		Request    string    `json:"request"`
62		From       string    `json:"from"`
63		To         string    `json:"to"`
64		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
65		Time       time.Time `json:"time"`
66		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
67	}
68	
69	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
70	type ReturnResult struct {
71		Request string    `json:"request"` // 退回请求号
72		Handoff string    `json:"handoff"` // 被退回的原交接请求号
73		From    string    `json:"from"`    // 退回源站（原交接目的站）
74		To      string    `json:"to"`      // 退回目的站（原交接源站）
75		Reason  string    `json:"reason"`
76		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
77		Time    time.Time `json:"time"`
78	}
79	
80	// ReceiptEntry 是批次内一件包裹的回执记录。
81	type ReceiptEntry struct {
82		Request string    `json:"request"`          // 回执请求号
83		Result  string    `json:"result"`           // 签收 | 失败
84		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
85		Time    time.Time `json:"time"`
86	}
87	
88	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
89	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
90	type BatchResult struct {
91		Batch    string                   `json:"batch"`
92		Station  string                   `json:"station"`  // 出发站
93		Courier  string                   `json:"courier"`  // 配送员
94		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
95		Time     time.Time                `json:"time"`     // 出站时间
96		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
97		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
98		AbortedBy string `json:"abortedBy,omitempty"`
99		// TransferredBy 为把该批次关闭为“已转交”的续接请求号（未转交为空）；
100		// 转交永久生效，与中止互斥，批次不得复用。
101		TransferredBy string `json:"transferredBy,omitempty"`
102		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
103		// 与创建本批次的续接请求号（普通出站批次为空）。
104		RelayedFrom  string `json:"relayedFrom,omitempty"`
105		RelayRequest string `json:"relayRequest,omitempty"`
106	}
107	
108	// Done 报告批次是否已完成（全部成员均已回执）。
109	func (b *BatchResult) Done() bool { return len(b.Receipts) == len(b.Parcels) }
110	
111	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
112	type ReceiptResult struct {
113		Request string    `json:"request"` // 回执请求号
114		Batch   string    `json:"batch"`   // 所属配送批次号
115		Parcel  string    `json:"parcel"`  // 包裹编号
116		Result  string    `json:"result"`  // 签收 | 失败
117		Reason  string    `json:"reason,omitempty"`
118		Time    time.Time `json:"time"`
119	}
120	
121	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
122	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
123	type FreezeResult struct {
124		Incident string    `json:"incident"` // 异常单号
125		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
126		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
127		Reason   string    `json:"reason"`   // 清理后的冻结原因
128		Time     time.Time `json:"time"`     // 冻结时间
129		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
130		ReleasedBy string `json:"releasedBy,omitempty"`
131	}
132	
133	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
134	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
135	type UnfreezeResult struct {
136		Request  string    `json:"request"`  // 解除请求号
137		Incident string    `json:"incident"` // 被解除的异常单号
138		Parcel   string    `json:"parcel"`   // 对应包裹编号
139		Note     string    `json:"note"`     // 清理后的处理说明
140		Time     time.Time `json:"time"`     // 解除时间
141	}
142	
143	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
144	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
145	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
146	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
147	type AbortResult struct {
148		Request string    `json:"request"` // 中止请求号
149		Batch   string    `json:"batch"`   // 被中止的配送批次号
150		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
151		Reason  string    `json:"reason"`  // 清理后的中止原因
152		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
153		Time    time.Time `json:"time"`    // 中止时间
154	}
155	
156	// TransferResult 记录一次成功的配送途中整批续接，用于续接请求号去重与结果重放。
157	// 续接表示原配送员把原批次全部尚未回执的包裹在配送途中交给另一配送员：
158	// 新批次按原顺序接纳全部未回执件继续配送，包裹保持“配送中”及原站点，
159	// 原批次永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他
160	// 业务编号同名；失败的首次续接不占用请求号。
161	type TransferResult struct {
162		Request     string    `json:"request"`     // 续接请求号
163		FromBatch   string    `json:"fromBatch"`   // 原批次号
164		ToBatch     string    `json:"toBatch"`     // 新批次号
165		Station     string    `json:"station"`     // 出发站（沿用原批次）
166		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
167		ToCourier   string    `json:"toCourier"`   // 新配送员
168		Reason      string    `json:"reason"`      // 清理后的续接原因
169		Parcels     []string  `json:"parcels"`     // 首次转交集合（原批次未回执成员，按原成员顺序）
170		Time        time.Time `json:"time"`        // 接手时间
171	}
172	
173	// ledgerFile 是本地数据文件的磁盘结构。
174	type ledgerFile struct {
175		Version   int                        `json:"version"`
176		Parcels   map[string]*Parcel         `json:"parcels"`
177		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
178		Returns   map[string]*ReturnResult   `json:"returns"`
179		Batches   map[string]*BatchResult    `json:"batches"`
180		Receipts  map[string]*ReceiptResult  `json:"receipts"`
181		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
182		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
183		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
184		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
185	}
186	
187	// Store 是一个数据文件对应的包裹站点交接台账。
188	type Store struct {
189		path string
190		data ledgerFile
191	}
192	
193	var (
194		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
195		ErrCorrupt = errors.New("数据文件已损坏")
196		// ErrNotFound 表示包裹编号在台账中不存在。
197		ErrNotFound = errors.New("包裹不存在")
198	)
199	
200	// Open 打开（或在文件不存在时建立）一个本地台账。
201	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
202	func Open(path string) (*Store, error) {
203		s := &Store{path: path}
204		raw, err := os.ReadFile(path)
205		if err != nil {
206			if os.IsNotExist(err) {
207				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
208					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
209					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
210					Transfers: map[string]*TransferResult{}}
211				return s, nil
212			}
213			return nil, fmt.Errorf("读取数据文件失败: %w", err)
214		}
215		if len(bytes.TrimSpace(raw)) == 0 {
216			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
217		}
218		if err := json.Unmarshal(raw, &s.data); err != nil {
219			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
220		}
221		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
222			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
223		}
224		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort 相关字段：按空表处理，无需手工修改。
225		if s.data.Returns == nil {
226			s.data.Returns = map[string]*ReturnResult{}
227		}
228		if s.data.Batches == nil {
229			s.data.Batches = map[string]*BatchResult{}
230		}
231		if s.data.Receipts == nil {
232			s.data.Receipts = map[string]*ReceiptResult{}
233		}
234		if s.data.Freezes == nil {
235			s.data.Freezes = map[string]*FreezeResult{}
236		}
237		if s.data.Unfreezes == nil {
238			s.data.Unfreezes = map[string]*UnfreezeResult{}
239		}
240		if s.data.Aborts == nil {
241			s.data.Aborts = map[string]*AbortResult{}
242		}
243		if s.data.Transfers == nil {
244			s.data.Transfers = map[string]*TransferResult{}
245		}
246		for _, b := range s.data.Batches {
247			if b != nil && b.Receipts == nil {
248				b.Receipts = map[string]*ReceiptEntry{}
249			}
250		}
251		if err := s.data.validate(); err != nil {
252			return nil, err
253		}
254		return s, nil
255	}
256	
257	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
258	func (l *ledgerFile) validate() error {
259		for id, p := range l.Parcels {
260			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
261				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
262			}
263			switch p.Status {
264			case statusInStation, statusDelivering, statusSigned, statusFrozen:
265			default:
266				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
267			}
268			for i, e := range p.Trail {
269				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
270					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
271				}
272				if e.Op == "退回" {
273					if e.Request == "" || e.Reason == "" || e.From == "" {
274						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
275					}
276					if _, ok := l.Handoffs[e.RefRequest]; !ok {
277						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
278					}
279				}
280				if e.Op == "出站" {
281					if e.Batch == "" || e.Courier == "" {
282						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
283					}
284					if _, ok := l.Batches[e.Batch]; !ok {
285						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
286					}
287				}
288				if e.Op == "回执" {
289					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
290						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
291					}
292					if e.Result == resultFailed && e.Reason == "" {
293						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
294					}
295					if _, ok := l.Batches[e.Batch]; !ok {
296						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
297					}
298				}
299				if e.Op == "收回" {
300					if e.Batch == "" || e.Request == "" || e.Reason == "" {
301						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
302					}
303					a, ok := l.Aborts[e.Request]
304					if !ok {
305						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
306					}
307					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
308						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
309					}
310					inAbort := false
311					for _, pid := range a.Parcels {
312						if pid == id {
313							inAbort = true
314							break
315						}
316					}
317					if !inAbort {
318						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
319					}
320				}
321				if e.Op == "续接" {
322					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
323						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
324					}
325					t, ok := l.Transfers[e.Request]
326					if !ok {
327						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
328					}
329					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
330						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
331						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
332					}
333					inTransfer := false
334					for _, pid := range t.Parcels {
335						if pid == id {
336							inTransfer = true
337							break
338						}
339					}
340					if !inTransfer {
341						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
342					}
343				}
344				if e.Op == "冻结" {
345					if e.Incident == "" || e.Reason == "" {
346						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
347					}
348					f, ok := l.Freezes[e.Incident]
349					if !ok {
350						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
351					}
352					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
353						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
354					}
355				}
356				if e.Op == "解除冻结" {
357					if e.Incident == "" || e.Request == "" || e.Note == "" {
358						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
359					}
360					f, ok := l.Freezes[e.Incident]
361					if !ok {
362						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
363					}
364					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
365						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
366					}
367					u, ok := l.Unfreezes[e.Request]
368					if !ok || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
369						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
370					}
371				}
372			}
373		}
374		for req, h := range l.Handoffs {
375			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
376				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
377			}
378			for _, id := range h.Parcels {
379				if _, ok := l.Parcels[id]; !ok {
380					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
381				}
382			}
383			if h.ReturnedBy != "" {
384				r, ok := l.Returns[h.ReturnedBy]
385				if !ok || r.Handoff != req {
386					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
387				}
388			}
389		}
390		for req, r := range l.Returns {
391			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
392				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
393				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
394			}
395			h, ok := l.Handoffs[r.Handoff]
396			if !ok {
397				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
398			}
399			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
400				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
401			}
402			for _, id := range r.Parcels {
403				if _, ok := l.Parcels[id]; !ok {
404					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
405				}
406			}
407		}
408		for id, b := range l.Batches {
409			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
410				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
411			}
412			seen := make(map[string]bool, len(b.Parcels))
413			for _, pid := range b.Parcels {
414				if seen[pid] {
415					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
416				}
417				seen[pid] = true
418				if _, ok := l.Parcels[pid]; !ok {
419					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
420				}
421			}
422			for pid, e := range b.Receipts {
423				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
424					(e.Result != resultSigned && e.Result != resultFailed) ||
425					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
426					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
427				}
428				rc, ok := l.Receipts[e.Request]
429				if !ok || rc.Batch != id || rc.Parcel != pid {
430					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
431				}
432			}
433			if b.AbortedBy != "" {
434				a, ok := l.Aborts[b.AbortedBy]
435				if !ok || a.Batch != id {
436					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
437				}
438			}
439			if b.TransferredBy != "" {
440				if b.AbortedBy != "" {
441					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
442				}
443				t, ok := l.Transfers[b.TransferredBy]
444				if !ok || t.FromBatch != id {
445					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
446				}
447			}
448			if b.RelayedFrom != "" {
449				t, ok := l.Transfers[b.RelayRequest]
450				if !ok || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
451					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
452						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
453				}
454			} else if b.RelayRequest != "" {
455				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
456			}
457		}
458		for req, rc := range l.Receipts {
459			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
460				(rc.Result != resultSigned && rc.Result != resultFailed) ||
461				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
462				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
463			}
464			b, ok := l.Batches[rc.Batch]
465			if !ok {
466				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
467			}
468			e, ok := b.Receipts[rc.Parcel]
469			if !ok || e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) {
470				return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
471			}
472		}
473		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序），且每件收回包裹的
474		// 轨迹中都有与该中止请求一致的收回记录；中止记录与收回轨迹不一致即损坏。
475		for req, a := range l.Aborts {
476			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
477				len(a.Parcels) == 0 || a.Time.IsZero() {
478				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
479			}
480			b, ok := l.Batches[a.Batch]
481			if !ok {
482				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
483			}
484			if b.AbortedBy != req {
485				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
486			}
487			if a.Station != b.Station {
488				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
489			}
490			expect := make([]string, 0, len(b.Parcels))
491			for _, pid := range b.Parcels {
492				if _, done := b.Receipts[pid]; !done {
493					expect = append(expect, pid)
494				}
495			}
496			if len(expect) != len(a.Parcels) {
497				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
498			}
499			for i := range expect {
500				if expect[i] != a.Parcels[i] {
501					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
502				}
503			}
504			for _, pid := range a.Parcels {
505				p, ok := l.Parcels[pid]
506				if !ok {
507					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
508				}
509				found := false
510				for _, e := range p.Trail {
511					if e.Op == "收回" && e.Request == req {
512						found = true
513						break
514					}
515				}
516				if !found {
517					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
518				}
519			}
520		}
521		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
522		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
523		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
524		for req, t := range l.Transfers {
525			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
526				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
527				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
528				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
529			}
530			fb, ok := l.Batches[t.FromBatch]
531			if !ok {
532				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
533			}
534			if fb.TransferredBy != req {
535				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
536			}
537			if fb.Station != t.Station || fb.Courier != t.FromCourier {
538				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
539			}
540			nb, ok := l.Batches[t.ToBatch]
541			if !ok {
542				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
543			}
544			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
545				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
546			}
547			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
548				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
549			}
550			expect := make([]string, 0, len(fb.Parcels))
551			for _, pid := range fb.Parcels {
552				if _, done := fb.Receipts[pid]; !done {
553					expect = append(expect, pid)
554				}
555			}
556			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
557				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
558					ErrCorrupt, req, t.FromBatch, t.ToBatch)
559			}
560			for _, pid := range t.Parcels {
561				p, ok := l.Parcels[pid]
562				if !ok {
563					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
564				}
565				found := false
566				for _, e := range p.Trail {
567					if e.Op == "续接" && e.Request == req {
568						found = true
569						break
570					}
571				}
572				if !found {
573					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
574				}
575			}
576		}
577		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
578		// 再核对两张结果表与包裹当前状态的对应关系。
579		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
580		for id, p := range l.Parcels {
581			var open string
582			for i, e := range p.Trail {
583				switch e.Op {
584				case "冻结":
585					if open != "" {
586						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
587							ErrCorrupt, id, i+1, open)
588					}
589					open = e.Incident
590				case "解除冻结":
591					if open != e.Incident {
592						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
593							ErrCorrupt, id, i+1, e.Incident, open)
594					}
595					open = ""
596				}
597			}
598			if p.Status == statusFrozen && open == "" {
599				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
600			}
601			if p.Status != statusFrozen && open != "" {
602				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
603			}
604			if open != "" {
605				openIncident[id] = open
606			}
607		}
608		for no, f := range l.Freezes {
609			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
610				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
611			}
612			p, ok := l.Parcels[f.Parcel]
613			if !ok {
614				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
615			}
616			if f.ReleasedBy == "" && p.Station != f.Station {
617				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
618					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
619			}
620			if f.ReleasedBy != "" {
621				u, ok := l.Unfreezes[f.ReleasedBy]
622				if !ok || u.Incident != no || u.Parcel != f.Parcel {
623					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
624				}
625			}
626		}
627		activeByParcel := make(map[string]string)
628		for req, u := range l.Unfreezes {
629			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
630				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
631			}
632			f, ok := l.Freezes[u.Incident]
633			if !ok {
634				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
635			}
636			if f.Parcel != u.Parcel {
637				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
638			}
639			if f.ReleasedBy != req {
640				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
641			}
642		}
643		for no, f := range l.Freezes {
644			if f.ReleasedBy != "" {
645				continue
646			}
647			if other, dup := activeByParcel[f.Parcel]; dup {
648				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
649			}
650			activeByParcel[f.Parcel] = no
651			if openIncident[f.Parcel] != no {
652				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
653					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
654			}
655			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
656				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
657			}
658		}
659		return nil
660	}
