662	// Register 执行单件收件登记并将结果整体落盘。
663	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
664		if _, ok := s.data.Parcels[id]; ok {
665			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
666		}
667		p := &Parcel{
668			ID:         id,
669			Station:    station,
670			Status:     statusInStation,
671			Registered: now,
672			Trail: []Event{{
673				Op:      "收件",
674				Station: station,
675				Time:    now,
676			}},
677		}
678		s.data.Parcels[id] = p
679		if err := s.save(); err != nil {
680			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
681			return nil, err
682		}
683		return p, nil
684	}
