686	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
687	func (s *Store) Query(id string) (*Parcel, error) {
688		p, ok := s.data.Parcels[id]
689		if !ok {
690			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
691		}
692		return p, nil
693	}
