707	// Handoff 提交一次多件包裹的站点交接。
708	//
709	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
710	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
711	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
712	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
713	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
714		if saved, ok := s.data.Handoffs[request]; ok {
715			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
716				return saved, true, nil
717			}
718			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
719		}
720	
721		// 首次提交：先做全部校验，任何一件不满足都整体失败。
722		for _, id := range parcels {
723			p, ok := s.data.Parcels[id]
724			if !ok {
725				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
726			}
727			if p.Station != from {
728				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
729			}
730			if inc := activeFreeze(p); inc != "" {
731				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
732			}
733			if p.Status != statusInStation {
734				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
735			}
736		}
737	
738		res := &HandoffResult{
739			Request: request,
740			From:    from,
741			To:      to,
742			Parcels: append([]string(nil), parcels...),
743			Time:    now,
744		}
745		s.data.Handoffs[request] = res
746	
747		// 记录旧值，落盘失败时整体回滚。
748		prev := make(map[string]struct {
749			station string
750			trail   []Event
751		}, len(parcels))
752		for _, id := range parcels {
753			p := s.data.Parcels[id]
754			prev[id] = struct {
755				station string
756				trail   []Event
757			}{p.Station, append([]Event(nil), p.Trail...)}
758			p.Station = to
759			p.Status = statusInStation
760			p.Trail = append(p.Trail, Event{
761				Op:      "交接",
762				Station: to,
763				Request: request,
764				Time:    now,
765			})
766		}
767	
768		if err := s.save(); err != nil {
769			delete(s.data.Handoffs, request)
770			for id, old := range prev {
771				p := s.data.Parcels[id]
772				p.Station = old.station
773				p.Trail = old.trail
774			}
775			return nil, false, err
776		}
777		return res, false, nil
778	}
779	
780	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
781	//
782	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
783	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
784	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
785	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
786	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
787	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
788	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
789	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
790		if saved, ok := s.data.Returns[request]; ok {
791			if saved.Handoff == handoffReq && saved.Reason == reason {
792				return saved, true, nil
793			}
794			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
795				request, saved.Handoff, saved.Reason)
796		}
797	
798		h, ok := s.data.Handoffs[handoffReq]
799		if !ok {
800			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
801		}
802		if h.ReturnedBy != "" {
803			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
804		}
805	
806		// 先做全部校验，任何一件不满足都整批拒绝。
807		for _, id := range h.Parcels {
808			p, ok := s.data.Parcels[id]
809			if !ok {
810				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
811			}
812			if inc := activeFreeze(p); inc != "" {
813				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
814			}
815			if p.Station != h.To || p.Status != statusInStation {
816				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
817					id, p.Station, p.Status, h.To)
818			}
819			last := lastFlowEvent(p.Trail)
820			if last.Op != "交接" || last.Request != handoffReq {
821				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
822					id, handoffReq)
823			}
824		}
825	
826		res := &ReturnResult{
827			Request: request,
828			Handoff: handoffReq,
829			From:    h.To,
830			To:      h.From,
831			Reason:  reason,
832			Parcels: append([]string(nil), h.Parcels...),
833			Time:    now,
834		}
835		s.data.Returns[request] = res
836		h.ReturnedBy = request
837	
838		// 记录旧值，落盘失败时整体回滚。
839		prev := make(map[string]struct {
840			station string
841			trail   []Event
842		}, len(h.Parcels))
843		for _, id := range h.Parcels {
844			p := s.data.Parcels[id]
845			prev[id] = struct {
846				station string
847				trail   []Event
848			}{p.Station, append([]Event(nil), p.Trail...)}
849			p.Station = h.From
850			p.Status = statusInStation
851			p.Trail = append(p.Trail, Event{
852				Op:         "退回",
853				Station:    h.From,
854				From:       h.To,
855				Request:    request,
856				RefRequest: handoffReq,
857				Reason:     reason,
858				Time:       now,
859			})
860		}
861	
862		if err := s.save(); err != nil {
863			delete(s.data.Returns, request)
864			h.ReturnedBy = ""
865			for id, old := range prev {
866				p := s.data.Parcels[id]
867				p.Station = old.station
868				p.Trail = old.trail
869			}
870			return nil, false, err
871		}
872		return res, false, nil
873	}
874	
875	// Dispatch 提交一次配送批次出站。
876	//
877	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
878	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
879	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
880	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
881	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
882	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
883		if saved, ok := s.data.Batches[batch]; ok {
884			if saved.RelayedFrom != "" {
885				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
886					batch, saved.RelayRequest, saved.RelayedFrom)
887			}
888			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
889				return saved, true, nil
890			}
891			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
892		}
893	
894		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
895		for _, id := range parcels {
896			p, ok := s.data.Parcels[id]
897			if !ok {
898				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
899			}
900			if p.Station != station {
901				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
902			}
903			if inc := activeFreeze(p); inc != "" {
904				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
905			}
906			if p.Status != statusInStation {
907				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
908			}
909		}
910	
911		res := &BatchResult{
912			Batch:    batch,
913			Station:  station,
914			Courier:  courier,
915			Parcels:  append([]string(nil), parcels...),
916			Time:     now,
917			Receipts: map[string]*ReceiptEntry{},
918		}
919		s.data.Batches[batch] = res
920	
921		// 记录旧值，落盘失败时整体回滚。
922		prev := make(map[string]struct {
923			status string
924			trail  []Event
925		}, len(parcels))
926		for _, id := range parcels {
927			p := s.data.Parcels[id]
928			prev[id] = struct {
929				status string
930				trail  []Event
931			}{p.Status, append([]Event(nil), p.Trail...)}
932			p.Status = statusDelivering // 站点不变，仍记出发站
933			p.Trail = append(p.Trail, Event{
934				Op:      "出站",
935				Station: station,
936				Batch:   batch,
937				Courier: courier,
938				Time:    now,
939			})
940		}
941	
942		if err := s.save(); err != nil {
943			delete(s.data.Batches, batch)
944			for id, old := range prev {
945				p := s.data.Parcels[id]
946				p.Status = old.status
947				p.Trail = old.trail
948			}
949			return nil, false, err
950		}
951		return res, false, nil
952	}
