1051	// ReceiptImportRecord 是回执整批导入文件中的一条记录（已清洗）。
1052	type ReceiptImportRecord struct {
1053		Request string // 回执请求号（与逐件 receipt 共用去重范围）
1054		Batch   string // 配送批次号
1055		Parcel  string // 包裹编号
1056		Result  string // 签收 | 失败
1057		Reason  string // 失败原因（失败时非空，签收时为空）
1058	}
1059	
1060	// ReceiptImportItem 是整批导入中一条记录的处理结果，按文件顺序排列。
1061	type ReceiptImportItem struct {
1062		Record   ReceiptImportRecord // 清洗后的记录内容
1063		Time     time.Time           // 发生时间（重放时为首次保存的时间）
1064		Replayed bool                // true 表示同内容历史重放，未产生新变更
1065	}
1066	
1067	// ImportReceipts 按文件顺序整批应用回执记录。
1068	//
1069	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1070	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1071	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
1072	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
1073	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
1074	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
1075	// 全部为历史重放时不改写台账。
1076	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
1077		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
1078		work, err := s.fork()
1079		if err != nil {
1080			return nil, err
1081		}
1082		items := make([]ReceiptImportItem, 0, len(records))
1083		hasNew := false
1084		for i, rec := range records {
1085			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
1086			if err != nil {
1087				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
1088			}
1089			if !replayed {
1090				hasNew = true
1091			}
1092			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed})
1093		}
1094		if !hasNew {
1095			return items, nil // 全部为历史重放：不改写台账
1096		}
1097	
1098		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
1099		orig := s.data
1100		s.data = work.data
1101		if err := s.save(); err != nil {
1102			s.data = orig
1103			return nil, err
1104		}
1105		return items, nil
1106	}
