1121	// Freeze 对一件在站包裹登记异常冻结。
1122	//
1123	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
1124	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
1125	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
1126	// 冻结只是管理记录，不移动实物、不算新流转。
1127	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
1128	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
1129	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
1130	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
1131	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
1132		if saved, ok := s.data.Freezes[incident]; ok {
1133			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
1134				return saved, true, nil
1135			}
1136			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
1137				incident, saved.Parcel, saved.Station, saved.Reason)
1138		}
1139	
1140		p, ok := s.data.Parcels[parcel]
1141		if !ok {
1142			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
1143		}
1144		if p.Station != station {
1145			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1146		}
1147		if p.Status != statusInStation {
1148			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1149		}
1150	
1151		res = &FreezeResult{
1152			Incident: incident,
1153			Parcel:   parcel,
1154			Station:  station,
1155			Reason:   reason,
1156			Time:     now,
1157		}
1158		s.data.Freezes[incident] = res
1159	
1160		// 记录旧值，落盘失败时整体回滚。
1161		oldStatus := p.Status
1162		oldTrail := append([]Event(nil), p.Trail...)
1163		p.Status = statusFrozen // 站点不变
1164		p.Trail = append(p.Trail, Event{
1165			Op:       "冻结",
1166			Station:  station,
1167			Incident: incident,
1168			Reason:   reason,
1169			Time:     now,
1170		})
1171	
1172		if err := s.save(); err != nil {
1173			delete(s.data.Freezes, incident)
1174			p.Status, p.Trail = oldStatus, oldTrail
1175			return nil, false, err
1176		}
1177		return res, false, nil
1178	}
